settings.custom_liquid:
{% liquid
  assign collection_title = closest.collection.metafields.custom.alternative_collection_title | default: closest.collection.title
  assign desc_parts = closest.collection.description | split: '<!-- split -->'
  assign intro_html = desc_parts | first
%}
<div class="collection-header-spacer">
<h1 class="h2">{{ collection_title }}</h1>
<div class="collection-intro">{{ intro_html }}</div>
</div>
{% if closest.collection.handle == 'milk-based' %}
<script type="application/ld+json">{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What does milk-based coffee mean?","acceptedAnswer":{"@type":"Answer","text":"Milk-based coffee refers to espresso-based drinks that include steamed or textured milk. Classics like lattes, flat whites and cappuccinos balance the boldness of espresso with the creaminess of milk, creating a smooth and flavourful cup."}},{"@type":"Question","name":"What are milk-based coffee beans?","acceptedAnswer":{"@type":"Answer","text":"Milk-based coffee beans are blends roasted to complement milk\u2019s natural sweetness and texture. At ONA Coffee, our milk-based blends are masterfully crafted to enhance chocolate, caramel, nut and berry notes, ensuring a rich, well-balanced cup with milk."}},{"@type":"Question","name":"Is Unwind a good coffee blend for milk-based coffee?","acceptedAnswer":{"@type":"Answer","text":"Absolutely! Unwind is a decaf blend designed to deliver a specialty coffee experience without caffeine, making it an excellent coffee base for milky coffee types. Its smooth chocolate and soft orange notes blend beautifully with milk, creating a rich, well-balanced cup. Whether you prefer a latte, flat white, or cappuccino, Unwind offers the best coffee with milk for those looking to enjoy a full-flavoured experience without the buzz."}}]}</script>
{% endif %}
{% if closest.collection.handle == 'filter' %}
<script type="application/ld+json">{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What is the difference between ground coffee and filtered coffee?","acceptedAnswer":{"@type":"Answer","text":"Ground coffee refers to any coffee that has been ground from whole beans, while filtered coffee specifically refers to coffee that is brewed using a filter method, such as pour-overs, drips or batch brews.\n\nFilter coffee beans are typically roasted and ground to suit slower extraction methods, bringing out clarity, sweetness and nuanced flavours that shine in filtered brewing."}},{"@type":"Question","name":"How do I make perfect filtered coffee?","acceptedAnswer":{"@type":"Answer","text":"Brewing the perfect filtered coffee is all about precision, freshness and making small adjustments. To bring out the best flavour from your drip filter coffee, we recommend:\n\n1. Using freshly roasted, high-quality filter coffee beans for optimal flavour.\n2. Grinding just before brewing to preserve aroma and complexity.\n3. Maintaining water temperature between 88\u201390\u00b0C for balanced extraction.\n4. Experimenting with grind size, water-to-coffee ratio and brew time to fine-tune your filtered coffee experience.\n\nFor coffee-bean-specific methods, view our brew guides."}}]}</script>
{% endif %}
<style>
  .collection-header-spacer { padding-top: var(--header-group-height, 131px); }
  .collection-intro { width: 100%; }
  .collection-intro p { margin: 0 0 1em; line-height: 1.6; }
  .collection-intro p:last-child { margin-bottom: 0; }
</style>

{% liquid
  assign desc_parts = closest.collection.description | split: '<!-- split -->'
  assign below_fold_html = desc_parts[1]
%}
{% if below_fold_html != blank %}
  <div class="collection-below-fold">
    {{ below_fold_html }}
  </div>
  <style>
    .collection-below-fold { width: 100%; }
    .collection-below-fold h2 { margin: 1.5em 0 0.5em; font-size: 1.5rem; }
    .collection-below-fold h2:first-child { margin-top: 0; }
    .collection-below-fold p { margin: 0 0 1em; line-height: 1.6; }
    .collection-below-fold a { text-decoration: underline; }
    .collection-below-fold__read-more { margin-top: 8px; }
  </style>
  <script>
    (function () {
      document.querySelectorAll('.collection-below-fold .readmore-text').forEach(function (block) {
        if (block.dataset.readmoreInit) return;
        block.dataset.readmoreInit = '1';
        block.style.display = 'none';
        var button = document.createElement('button');
        button.type = 'button';
        button.className = 'button-secondary collection-below-fold__read-more';
        button.textContent = 'Read more';
        button.setAttribute('aria-expanded', 'false');
        block.parentNode.insertBefore(button, block);
        button.addEventListener('click', function () {
          var expanded = block.style.display !== 'none';
          block.style.display = expanded ? 'none' : '';
          button.textContent = expanded ? 'Read more' : 'Read less';
          button.setAttribute('aria-expanded', String(!expanded));
        });
      });
    })();
  </script>
{% endif %}

{% liquid
  assign faqs = closest.collection.metafields.custom.faqs.value
%}
{% if faqs.size > 0 %}
  <div class="collection-faqs">
    <h2 class="collection-faqs__heading"><em>FAQs</em></h2>
    <div class="collection-faqs__list">
      {% for faq in faqs %}
        <details class="collection-faqs__item">
          <summary class="collection-faqs__question">
            <span>{{ faq.question }}</span>
            <span class="collection-faqs__icon" aria-hidden="true"></span>
          </summary>
          <div class="collection-faqs__answer">{{ faq.answer | metafield_tag }}</div>
        </details>
      {% endfor %}
    </div>
  </div>
  <style>
    .collection-faqs { width: 100%; max-width: 46rem; margin: 0 auto; }
    .collection-faqs__heading { text-align: center; font-size: 2rem; margin: 0 0 1.5em; }
    .collection-faqs__list { border-top: 1px solid var(--border-color); }
    .collection-faqs__item { border-bottom: 1px solid var(--border-color); }
    .collection-faqs__question {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1em;
      padding: 1em 0;
      cursor: pointer;
      font-weight: 600;
      list-style: none;
    }
    .collection-faqs__question::-webkit-details-marker { display: none; }
    .collection-faqs__icon { position: relative; width: 14px; height: 14px; flex-shrink: 0; }
    .collection-faqs__icon::before,
    .collection-faqs__icon::after {
      content: '';
      position: absolute;
      background: currentColor;
      transition: transform 0.15s ease, opacity 0.15s ease;
    }
    .collection-faqs__icon::before { top: 6px; left: 0; width: 14px; height: 2px; }
    .collection-faqs__icon::after { top: 0; left: 6px; width: 2px; height: 14px; }
    details[open] .collection-faqs__icon::after { transform: rotate(90deg); opacity: 0; }
    .collection-faqs__answer { padding: 0 0 1em; line-height: 1.6; }
    .collection-faqs__answer p { margin: 0; }
  </style>
{% endif %}
